const cleanupDb = new PrismaClient();
let testLearnerAdmission="";
const testAdmissionDraftIds:string[]=[];
const testParentUserIds:string[]=[];
let testOutOfScopeLearnerId="";
let testAssessmentId="";
let testAvatarUrl="";
